 function renderAnalytics(){const from=$('#analyticsFrom').value,to=$('#analyticsTo').value;if(from&&to&&from>to){$('#advancedMetrics').textContent='Choose a valid date range.';return;}const within=date=>(!from||date>=from)&&(!to||date<=to);const invoices=(state.invoices||[]).filter(i=>i.status==='active'&&within(i.sale_date));const expenses=state.transactions.filter(t=>['Expense','Transport Cost','Other Expense'].includes(t.type)&&within(t.txn_date));const activeIds=new Set((state.invoices||[]).filter(i=>i.status==='active').map(i=>i.id));const returns=(state.returns||[]).filter(r=>within(r.return_date)&&activeIds.has(r.invoice_id));const sum=(rows,fn)=>moneyRound(rows.reduce((s,r)=>s+Number(fn(r)||0),0));const netSales=moneyRound(sum(invoices,i=>i.total_amount)-sum(returns,r=>r.credit)),cost=sum(expenses,t=>t.amount),refund=sum(returns,r=>r.refund);const cashflow=moneyRound(sum(invoices,i=>i.paid_amount)+sum(state.payments.filter(p=>within(p.payment_date)),p=>p.amount)+sum(state.transactions.filter(t=>t.type==='Other Income'&&within(t.txn_date)),t=>t.amount)-cost-refund-sum(state.transactions.filter(t=>t.type==='Company Payment'&&within(t.txn_date)),t=>t.amount));const metrics=[['Net Sales · Period',netSales],['Discounts',sum(invoices,i=>i.discount)],['Return Credits',sum(returns,r=>r.credit)],['Operating Expenses',cost],['Net Cash Flow',cashflow],['Stock Value · Selling Price',sum(state.products,p=>Number(p.current_stock)*Number(p.default_rate))]];$('#advancedMetrics').innerHTML=metrics.map(([name,value])=>`<div class="analytics-metric"><span>${name}</span><strong>${formatMoney(value)}</strong></div>`).join('');const products=new Map();for(const inv of invoices)for(const i of inv.items){const amount=moneyRound(i.line_total*(i.quantity-i.returned_quantity)/i.quantity);products.set(i.product_name,moneyRound((products.get(i.product_name)||0)+amount));}const top=[...products].sort((a,b)=>b[1]-a[1]).slice(0,5),max=Math.max(1,...top.map(p=>p[1]));$('#topProducts').innerHTML=top.length?top.map(([name,value])=>`<div class="analytics-bar"><span>${recordText(name)}<strong>${formatMoney(value)}</strong></span><meter value="${Math.max(0,value)}" min="0" max="${max}">${formatMoney(value)}</meter></div>`).join(''):'<p class="helper-text">No sales in this period.</p>';const categories=new Map();for(const e of expenses)categories.set(e.category||'General',moneyRound((categories.get(e.category||'General')||0)+Number(e.amount)));$('#expenseBreakdown').innerHTML=categories.size?[...categories].sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="breakdown-row"><span>${escapeHtml(name)}</span><strong>${formatMoney(value)}</strong></div>`).join(''):'<p class="helper-text">No expenses in this period.</p>';}
