  $('.app-shell').toggleAttribute('data-auth-pending',!authenticated);updateBackButton();
  $('#mainContent').inert=!authenticated;$('.sidebar').inert=!authenticated||(matchMedia('(max-width:760px)').matches&&!ui.menuOpen);$('.mobile-nav').inert=!authenticated;
  for(const el of $$('#searchBtn,#refreshBtn,#syncStatusButton,#menuBtn,.export-button')){if(el.tagName==='BUTTON')el.disabled=!authenticated;else el.inert=!authenticated;}
  $('#accountButton').setAttribute('aria-label',user?i18n.text('Account')+' · '+user.username:i18n.text('Log In'));
  $('#accountUserName').textContent=user?.username||'—';$('#accountUserRole').textContent=user?i18n.text(user.role==='admin'?'Admin / Master':'General User'):'—';
  $('#accountPendingNote').textContent=s.pending?i18n.text('Sync pending work before logging out.') : i18n.text('Use Switch Account to sign in as another user.');
  $('#accountLogoutButton').disabled=s.switching||s.flushing||s.pending>0;
